  builder_.add_PAYLOAD_HASH(PAYLOAD_HASH);
  builder_.add_FIELDS(FIELDS);
  builder_.add_SUBJECT_ID(SUBJECT_ID);
  builder_.add_KEY_EPOCH(KEY_EPOCH);
