  { auto _e = TAG(); if (_e) { _o->TAG.resize(_e->size()); std::copy(_e->begin(), _e->end(), _o->TAG.begin()); } }
  { auto _e = KEY_ID(); if (_e) _o->KEY_ID = _e->str(); }
  { auto _e = AAD_HASH(); if (_e) { _o->AAD_HASH.resize(_e->size()); std::copy(_e->begin(), _e->end(), _o->AAD_HASH.begin()); } }
