inline const FSM *GetFSM(const void *buf) {
  return ::flatbuffers::GetRoot<FSM>(buf);
}

inline const FSM *GetSizePrefixedFSM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<FSM>(buf);
}

inline const char *FSMIdentifier() {
  return "$FSM";
}

inline bool FSMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FSMIdentifier());
}

inline bool SizePrefixedFSMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, FSMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyFSMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<FSM>(FSMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedFSMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<FSM>(FSMIdentifier());
}

inline void FinishFSMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<FSM> root) {
  fbb.Finish(root, FSMIdentifier());
}

inline void FinishSizePrefixedFSMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<FSM> root) {
  fbb.FinishSizePrefixed(root, FSMIdentifier());
}

inline std::unique_ptr<FSMT> UnPackFSM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<FSMT>(GetFSM(buf)->UnPack(res));
}

inline std::unique_ptr<FSMT> UnPackSizePrefixedFSM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<FSMT>(GetSizePrefixedFSM(buf)->UnPack(res));
}

